import{z as o,x as s,o as r,c as d,q as A,j as n,D as i,d as E,s as l,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"金融素养与默认选项","description":"","frontmatter":{"title":"金融素养与默认选项","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/financial-literacy-defaults.md","filePath":"econ/financial-literacy-defaults.md","lastUpdated":1791063341000}'),p={name:"econ/financial-literacy-defaults.md"};function c(h,a,m,f,u,D){const t=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="金融素养与默认选项" tabindex="-1">金融素养与默认选项 <a class="header-anchor" href="#金融素养与默认选项" aria-label="Permalink to &quot;金融素养与默认选项&quot;">​</a></h1><div class="epigraph"><p>复利、风险分散和通胀，不是偏好参数；大量家庭答不对这三问。默认选项则在不改变菜单的情况下改写参与。</p><footer>—— Lusardi and Mitchell 的素养测量；Madrian and Shea, QJE 2001；Thaler and Benartzi, JPE 2004</footer></div><p><a href="/econ/household-portfolio-participation">上一课</a>把零持有写成成本与背景风险。本课缺口是：同样的菜单，理解力与<strong>默认</strong>仍移动角点。不重估固定成本，也不把助推课序提前写完——本课只落在家庭储蓄制度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lusardi 与 Mitchell 用三问（复利、通胀、分散）刻画素养：答对与股票参与、退休准备正相关。这不是新的 \\(\\gamma\\)，是预算与欧拉在头脑里没有被算出来。Madrian 与 Shea（2001）在 401(k) 里把默认从「不参加」改成「参加」，参与率跳跃——菜单没变，现状变了。Thaler 与 Benartzi（2004）的 Save More Tomorrow：承诺未来加薪时提高缴存，绕开现时偏差。Choi、Laibson、Madrian 与 Metrick 把默认、惯性与 Diversification 启发式写成同一组事实。</p><p>缺口是在参与之谜上叠加认知与选择架构，而不是重写 LCH。</p><p><span class="marginnote">惯性可以是理性的（计算成本）也可以是偏差（现状）。识别靠默认切换：成本几乎没变，选择变了，就不是单纯的固定参与成本。</span></p><p><span class="marginnote">术语翻译：默认选项就是「不填表也会发生的事」。它像食堂把苹果摆在收银台边、把薯条挪去柜台里层：菜单没变，够得着的先被拿走。Madrian–Shea 的发现正是如此——把 401(k) 从「默认不参加」翻成「默认参加」，多数人两边都不动，参与率随纸面默认走，而不是随深思熟虑走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把「理解欧拉」与「填写表格」分成两层。素养影响能否从菜单映射到最优；默认影响不填写时落到哪一点。经验设计：雇主默认的自然实验；素养与教育、课程干预。本课不估计干预的长期回报。</p>',10)),(r(),n(B,null,{default:i(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PART%5B%22%E5%8F%82%E4%B8%8E%E8%A7%92%E7%82%B9%22%5D%20--%3E%20LIT%5B%22%E7%B4%A0%E5%85%BB%3A%20%E8%83%BD%E5%90%A6%E7%AE%97%E5%87%BA%E5%88%86%E6%95%A3%E4%B8%8E%E5%A4%8D%E5%88%A9%22%5D%0A%20%20PART%20--%3E%20DEF%5B%22%E9%BB%98%E8%AE%A4%3A%20%E4%B8%8D%E5%A1%AB%E8%A1%A8%E8%90%BD%E5%88%B0%E5%93%AA%22%5D%0A%20%20DEF%20--%3E%20MAD%5B%22Madrian-Shea%3A%20%E9%BB%98%E8%AE%A4%E5%8F%82%E4%B8%8E%E8%B7%B3%E8%B7%83%22%5D%0A%20%20LIT%20--%3E%20SMRT%5B%22SMarT%3A%20%E7%94%A8%E6%9C%AA%E6%9D%A5%E5%8A%A0%E8%96%AA%E5%BD%93%E6%89%BF%E8%AF%BA%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与"),e("a",{href:"/econ/commitment-devices"},"承诺装置"),E("的接缝：默认和 SMarT 是制度版金蛋。与后课助推的接缝：这里对象是退休账户，一般选择架构留到行为单元。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制有两条。一条是信息：不懂分散的人把股票当赌博，零持有来自信念而非 \\(\\gamma=\\infty\\)。一条是惰性：填写成本或现时偏差使现状成为实质菜单。默认把现状从「现金」换成「目标日期基金」，参与与股票暴露同时上升。这不证明人的偏好变了，只证明揭示偏好依赖架构——显示偏好课已经警告过菜单依赖，本课给出现场。",-1)),(r(),n(B,null,{default:i(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%96%B0%E5%91%98%E5%B7%A5%E5%85%A5%E8%81%8C%EF%BC%9A%E8%8F%9C%E5%8D%95%E4%B8%8E%E8%A1%A5%E8%B4%B4%E5%AE%8C%E5%85%A8%E4%B8%8D%E5%8F%98%22%5D%20--%3E%20A%5B%22%E4%B8%96%E7%95%8C%E4%B8%80%EF%BC%9A%E9%BB%98%E8%AE%A4%E4%B8%8D%E5%8F%82%E5%8A%A0%22%5D%0A%20%20NEW%20--%3E%20B%5B%22%E4%B8%96%E7%95%8C%E4%BA%8C%EF%BC%9A%E9%BB%98%E8%AE%A4%E5%8F%82%E5%8A%A0%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%83%B3%E5%8F%82%E4%B8%8E%EF%BC%9A%E5%BF%85%E9%A1%BB%E4%B8%BB%E5%8A%A8%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E6%83%B3%E9%80%80%E5%87%BA%EF%BC%9A%E5%BF%85%E9%A1%BB%E4%B8%BB%E5%8A%A8%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20A1%20--%3E%20LAZY%5B%22%E6%83%B0%E6%80%A7%E6%8A%8A%E4%BA%BA%E7%95%99%E5%9C%A8%E9%BB%98%E8%AE%A4%22%5D%0A%20%20B1%20--%3E%20LAZY%0A%20%20A1%20--%3E%20OUT%5B%22%E5%8F%82%E4%B8%8E%E7%8E%87%E4%BD%8E%22%5D%0A%20%20B1%20--%3E%20IN%5B%22%E5%8F%82%E4%B8%8E%E7%8E%87%E8%B7%B3%E5%8D%87%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">数字实例：Lusardi–Mitchell 三问之一是复利题——「5% 年利率下，10 万元存两年是多少？」正确答案是 11.025 万元，因为第二年利息要按 10.5 万元的本息合计来算。多国调查里能答对全部三问的人常不到一半；答错的人面对复利与通胀产品，相当于没带地图进山路。</span></p><p>不进入限价簿。默认选项是人力资源与计划文件，不是报价档。主干在簿的交接处停；缴存默认改的是家庭菜单的现状，不是 tick。</p><p>三问素养测的是能否执行已有欧拉与分散，不是新的偏好公理。答错的人可能仍有完备传递的 \\(\\succsim\\)，只是没把复利映射到数字。默认实验的识别力在于菜单法律上不变：若选择仍跳，显示偏好就不能把「不参与」读成对股票的真实厌恶。SMarT 把加薪当未来菜单的自动收紧，是承诺装置的工资版。</p><p><span class="marginnote">直觉类比：SMarT 利用的是「明天的事不用今天忍」。让工人承诺「以后每次加薪都自动多缴几个点」，痛感被推到加薪之后，缴存却立刻锁定、随工资自动上调——把现时偏差反过来当杠杆用，而不是硬碰硬地与之对抗。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>素养与财富互为因果：有钱才学、会的人才积累。默认也可能给错误风险暴露（过高股票或过高收费基金）。本课不把「提高素养」写成充分政策。行为单元的框架效应会解释为何同一缴存率用「匹配」或「税」包装结果不同。</p><p>跨期选择单元到此收束。下一单元从<a href="/econ/expected-utility">期望效用</a>的缺口起：现场选择系统地偏离 vNM，前景理论接棒，仍不重推导独立性公理。</p><p>菜单法律上不变而选择跳，说明「不参与」不能直接读成对股票的厌恶。</p><p>跨期单元到此收束：下一单元从 vNM 的现场失败起，不重推独立性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>素养不足使欧拉与分散无法被执行；默认在菜单不变时改参与。</li><li>Madrian–Shea 与 SMarT 把承诺和惰性写成制度。</li><li>本单元不重写簿；家庭金融停在参与与缴存，下一单元改风险偏好的表示。</li><li>三问素养测执行，不测新的偏好公理。</li><li>SMarT 是承诺装置的加薪版。</li><li>出处：Lusardi and Mitchell；Madrian and Shea, <em>QJE</em> 2001；Thaler and Benartzi, <em>JPE</em> 2004。</li></ul>',11))])}const S=o(p,[["render",c]]);export{M as __pageData,S as default};
